#include <bits/stdc++.h>
using namespace std;

long long total_p, multiplier, visited_nodes[1000006], total_cycles;

long long mod_pow(long long base, long long exponent) {
    long long result = 1;
    for (int bit = 30; bit >= 0; bit--) {
        result = (result * result) % 1000000007;
        if ((1LL << bit) & exponent) {
            result = (result * base) % 1000000007;
        }
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    total_p = 0; multiplier = 0; total_cycles = 0;
    cin >> total_p >> multiplier;
    if (multiplier == 1) {
        cout << mod_pow(total_p, total_p);
        return 0;
    }
    for (int i = 1; i < total_p; i++) {
        if (!visited_nodes[i]) {
            visited_nodes[i] = 1;
            total_cycles++;
            long long current_node = (i * multiplier) % total_p;
            while (!visited_nodes[current_node]) {
                visited_nodes[current_node] = 1;
                current_node = (current_node * multiplier) % total_p;
            }
        }
    }
    cout << mod_pow(total_p, total_cycles);
}
